27	// servedModelName returns the model name clients address, defaulting to the
28	// object name when Spec.ModelName is unset.
29	func servedModelName(pm *modelv1alpha1.ModelClaim) string {
30		if pm.Spec.ModelName != nil && *pm.Spec.ModelName != "" {
31			return *pm.Spec.ModelName
32		}
33		return pm.Name
34	}
