44	// ipcNameFor derives the kvcached shared-memory segment name for a model. It
45	// must be unique per GPU so co-tenant engines do not collide on /dev/shm, and
46	// it is sanitized to match kvcached's own normalization (it replaces characters
47	// like '.' and '/' with '-'); otherwise kvctl operations would target a
48	// different segment name than the engine actually created.
49	func ipcNameFor(pm *modelv1alpha1.ModelClaim) string {
50		return "kvc_" + sanitizeIPCName(pm.Name)
51	}
52	
53	// sanitizeIPCName maps any character outside [A-Za-z0-9_-] to '-', matching how
54	// kvcached normalizes the KVCACHED_IPC_NAME (verified on real hardware: a name
55	// like "kvc_qwen3-0.6b" becomes "kvc_qwen3-0-6b").
56	func sanitizeIPCName(s string) string {
57		var b strings.Builder
58		b.Grow(len(s))
59		for _, r := range s {
60			switch {
61			case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '_', r == '-':
62				b.WriteRune(r)
63			default:
64				b.WriteRune('-')
65			}
66		}
67		return b.String()
68	}
69	
70	// LocalityProvider is an optional advisory estimate for bringing a model's
71	// weights onto a node. Runtime snapshots supply the authoritative per-pod
72	// artifact signal; this interface remains for future node-level hints. A zero
73	// cost means "already hot", and uniformLocality preserves load-only fallback.
74	type LocalityProvider interface {
75		Cost(model, nodeName string) float64
76	}
77	
78	// uniformLocality is the default: every node looks equally cheap, so locality
79	// never tips the decision and placement falls back to load + name ordering.
80	type uniformLocality struct{}
81	
82	func (uniformLocality) Cost(model, nodeName string) float64 { return 0 }
83	
84	// selectPodForActivation picks a warm pod to attach the model to. Among pods not
85	// already hosting this model, it chooses the lowest-cost pod, ranked
86	// lexicographically by (locality cost, current model load, name): prefer a node
87	// where the weights are already hot, then the least-loaded pod for density
88	// spread, breaking remaining ties by name for determinism.
89	//
90	// A nil provider is treated as uniform (load-only), preserving the existing
91	// deterministic fallback when runtime observations are unavailable.
92	func selectPodForActivation(candidates []corev1.Pod, alreadyOn map[string]bool, load map[string]int, model string, locality LocalityProvider) (*corev1.Pod, error) {
93		return selectPodForActivationWithState(candidates, alreadyOn, load, model, locality, nil)
94	}
95	
96	// selectPodForActivationWithState first prefers a pod that already has the
97	// artifact locally, then live GPU/KV observations, and finally the Phase-1
98	// locality/load/name rank. Missing runtime state is safe: it simply falls back
99	// to the existing deterministic placement behavior.
100	func selectPodForActivationWithState(
101		candidates []corev1.Pod,
102		alreadyOn map[string]bool,
103		load map[string]int,
104		model string,
105		locality LocalityProvider,
106		states map[string]PodPlacementState,
107	) (*corev1.Pod, error) {
108		if locality == nil {
109			locality = uniformLocality{}
110		}
111		var best *corev1.Pod
112		var bestState PodPlacementState
113		var bestLoc float64
114		var bestLoad int
115		for i := range candidates {
116			pod := &candidates[i]
117			if alreadyOn[pod.Name] {
118				continue
119			}
120			state := states[pod.Name]
121			loc := locality.Cost(model, pod.Spec.NodeName)
122			l := load[pod.Name]
123			if best == nil || placementStateLess(state, bestState) ||
124				(!placementStateLess(bestState, state) && rankLess(loc, l, pod.Name, bestLoc, bestLoad, best.Name)) {
125				best, bestState, bestLoc, bestLoad = pod, state, loc, l
126			}
127		}
128		if best == nil {
129			return nil, fmt.Errorf("no available candidate warm pod for model")
130		}
131		return best, nil
132	}
133	
134	// placementStateLess returns whether a ranks ahead of b using live runtime
135	// state. `false` in both directions means the legacy locality/load tie-breaker
136	// decides the winner.
137	func placementStateLess(a, b PodPlacementState) bool {
138		if a.ArtifactCached != b.ArtifactCached {
139			return a.ArtifactCached
140		}
141		if a.SnapshotKnown != b.SnapshotKnown {
142			return a.SnapshotKnown
143		}
144		if a.MemoryKnown != b.MemoryKnown {
145			return a.MemoryKnown
146		}
147		if a.MemoryKnown && a.HBMFreeBytes != b.HBMFreeBytes {
148			return a.HBMFreeBytes > b.HBMFreeBytes
149		}
150		if a.SnapshotKnown && a.KVUsedBytes != b.KVUsedBytes {
151			return a.KVUsedBytes < b.KVUsedBytes
152		}
153		if a.SnapshotKnown && a.ModelCount != b.ModelCount {
154			return a.ModelCount < b.ModelCount
155		}
156		return false
157	}
158	
159	// rankLess reports whether candidate (loc,load,name) ranks before
160	// (bLoc,bLoad,bName): lower locality cost first, then lower load, then lower name.
161	func rankLess(loc float64, load int, name string, bLoc float64, bLoad int, bName string) bool {
162		if loc != bLoc {
163			return loc < bLoc
164		}
165		if load != bLoad {
166			return load < bLoad
167		}
168		return name < bName
169	}
