15	*/
16	
17	package modelclaim
18	
19	import (
20		"bytes"
21		"encoding/json"
22		"errors"
23		"fmt"
24		"io"
25		"sort"
26		"strings"
27		"time"
28	)
29	
30	const poolReclaimModeKVFirst = "kv-first"
31	
32	// Fixed pool policy configuration error classes. They stay low-cardinality so
33	// Events can be deduplicated per class; the detailed parser message travels
34	// only in the Event and log text.
35	const (
36		poolPolicyErrorInvalidJSON     = "invalid_json"
37		poolPolicyErrorUnknownField    = "unknown_field"
38		poolPolicyErrorUnsupportedMode = "unsupported_mode"
39		poolPolicyErrorInvalidCapacity = "invalid_capacity"
40		poolPolicyErrorInvalidFloor    = "invalid_floor"
41		poolPolicyErrorInvalidSleep    = "invalid_sleep_window"
42	)
43	
44	var errPoolKVUsageExceedsCapacity = errors.New(
45		"observed KV usage and protected floors exceed pool capacity",
46	)
47	
48	// poolPolicyConfigError attaches a fixed error class to a configuration
49	// failure so operator-facing signals key on the class while keeping the full
50	// parser message for humans.
51	type poolPolicyConfigError struct {
52		class string
53		err   error
54	}
55	
56	func (e *poolPolicyConfigError) Error() string { return e.err.Error() }
57	
58	func (e *poolPolicyConfigError) Unwrap() error { return e.err }
59	
60	func poolPolicyErrorClass(err error) string {
61		var configErr *poolPolicyConfigError
62		if errors.As(err, &configErr) {
63			return configErr.class
64		}
65		return poolPolicyErrorInvalidJSON
66	}
67	
68	func poolPolicyDecodeErrorClass(err error) string {
69		// encoding/json exposes DisallowUnknownFields violations only through the
70		// error text, so class detection has to match on it.
71		if strings.Contains(err.Error(), "unknown field") {
72			return poolPolicyErrorUnknownField
73		}
74		return poolPolicyErrorInvalidJSON
75	}
76	
77	// poolPolicy is intentionally configured by one JSON Deployment annotation,
78	// not another resource. Reclaim adjusts kvcached ceilings; lifecycle parks an
79	// idle engine with vLLM sleep after request observations establish idleness.
80	type poolPolicy struct {
81		Reclaim   *poolReclaimPolicy   `json:"reclaim,omitempty"`
82		Lifecycle *poolLifecyclePolicy `json:"lifecycle,omitempty"`
83	}
84	
85	type poolReclaimPolicy struct {
86		Mode                   string `json:"mode,omitempty"`
87		CapacityBytes          int64  `json:"capacityBytes"`
88		GuaranteedFloorPercent int32  `json:"guaranteedFloorPercent,omitempty"`
89	}
90	
91	type poolLifecyclePolicy struct {
92		SleepAfterSeconds int64 `json:"sleepAfterSeconds"`
93	}
94	
95	// parsePoolPolicy decodes the Deployment policy annotation and rejects unknown
96	// keys. A typo must disable policy safely rather than silently changing GPU
97	// memory behavior.
98	func parsePoolPolicy(raw string) (*poolPolicy, error) {
99		decoder := json.NewDecoder(bytes.NewBufferString(raw))
100		decoder.DisallowUnknownFields()
101		policy := &poolPolicy{}
102		if err := decoder.Decode(policy); err != nil {
103			return nil, &poolPolicyConfigError{
104				class: poolPolicyDecodeErrorClass(err),
105				err:   fmt.Errorf("decode pool policy: %w", err),
106			}
107		}
108		if err := decoder.Decode(&struct{}{}); err != io.EOF {
109			if err == nil {
110				err = errors.New("multiple JSON values")
111			}
112			return nil, &poolPolicyConfigError{
113				class: poolPolicyErrorInvalidJSON,
114				err:   fmt.Errorf("decode pool policy: %w", err),
115			}
116		}
117		if policy.Reclaim != nil {
118			if policy.Reclaim.Mode == "" {
119				policy.Reclaim.Mode = poolReclaimModeKVFirst
120			}
121			if policy.Reclaim.Mode != poolReclaimModeKVFirst {
122				return nil, &poolPolicyConfigError{
123					class: poolPolicyErrorUnsupportedMode,
124					err:   fmt.Errorf("reclaim.mode must be %q", poolReclaimModeKVFirst),
125				}
126			}
127			if policy.Reclaim.CapacityBytes <= 0 {
128				return nil, &poolPolicyConfigError{
129					class: poolPolicyErrorInvalidCapacity,
130					err:   errors.New("reclaim.capacityBytes must be positive"),
131				}
132			}
133			if policy.Reclaim.GuaranteedFloorPercent < 0 ||
134				policy.Reclaim.GuaranteedFloorPercent > 100 {
135				return nil, &poolPolicyConfigError{
136					class: poolPolicyErrorInvalidFloor,
137					err:   errors.New("reclaim.guaranteedFloorPercent must be between 0 and 100"),
138				}
139			}
140		}
141		if policy.Lifecycle != nil && policy.Lifecycle.SleepAfterSeconds <= 0 {
142			return nil, &poolPolicyConfigError{
143				class: poolPolicyErrorInvalidSleep,
144				err:   errors.New("lifecycle.sleepAfterSeconds must be positive"),
145			}
146		}
147		return policy, nil
148	}
149	
150	type poolRequestActivity struct {
151		Active           bool
152		RequestsInFlight int64
153		CompletionDelta  int64
154		LastActive       time.Time
155		Initialized      bool
156	}
157	
158	type poolKVModel struct {
159		Name            string
160		KVUsedBytes     int64
161		KVCapacityBytes int64
162		Activity        poolRequestActivity
163	}
164	
165	// computePoolKVTargets distributes one explicit physical KV budget across the
166	// engines on a single GPU. Current KV usage is a hard lower bound: if retained
167	// pages plus floors already exceed the budget, it returns no plan instead of
168	// asking kvctl to force an unsafe shrink.
169	func computePoolKVTargets(
170		capacityBytes int64,
171		guaranteedFloorPercent int32,
172		models []poolKVModel,
173	) (map[string]int64, error) {
174		if capacityBytes <= 0 {
175			return nil, fmt.Errorf("pool capacity must be positive")
176		}
177		if guaranteedFloorPercent < 0 || guaranteedFloorPercent > 100 {
178			return nil, fmt.Errorf("guaranteed floor percent must be between 0 and 100")
179		}
180		if len(models) == 0 {
181			return nil, nil
182		}
183	
184		floorBytes := percentOf(capacityBytes, guaranteedFloorPercent)
185		targets := make(map[string]int64, len(models))
186		baseBytes := int64(0)
187		hasActiveModel := false
188		active := make([]poolKVModel, 0, len(models))
189		seen := make(map[string]struct{}, len(models))
190		for _, model := range models {
191			if model.Name == "" {
192				return nil, fmt.Errorf("pool model name must not be empty")
193			}
194			if _, found := seen[model.Name]; found {
195				return nil, fmt.Errorf("duplicate pool model %q", model.Name)
196			}
197			seen[model.Name] = struct{}{}
198			used := max(model.KVUsedBytes, 0)
199			base := max(floorBytes, used)
200			if baseBytes > capacityBytes-base {
201				return nil, errPoolKVUsageExceedsCapacity
202			}
203			baseBytes += base
204			targets[model.Name] = base
205			if model.Activity.Active {
206				hasActiveModel = true
207				active = append(active, model)
208			}
209		}
210		// Without demonstrable demand there is no pressure signal. Preserve the
211		// existing limits rather than shrinking idle engines merely because a
212		// controller just started or saw a quiet interval.
213		if !hasActiveModel {
214			return nil, nil
215		}
216	
217		remaining := capacityBytes - baseBytes
218		if remaining <= 0 {
219			return targets, nil
220		}
221		sort.Slice(active, func(i, j int) bool { return active[i].Name < active[j].Name })
222		weights := make(map[string]int64, len(active))
223		totalWeight := int64(0)
224		for _, model := range active {
225			weight := int64(1) + boundedActivity(model.Activity.RequestsInFlight) +
226				boundedActivity(model.Activity.CompletionDelta)
227			weights[model.Name] = weight
228			totalWeight += weight
229		}
230		if totalWeight == 0 {
231			return targets, nil
232		}
233	
234		granted := int64(0)
235		for _, model := range active {
236			grant := remaining * weights[model.Name] / totalWeight
237			targets[model.Name] += grant
238			granted += grant
239		}
240		// Give deterministic ownership to rounding remainders so successive ticks
241		// converge instead of oscillating on a one-byte difference.
242		for index := int64(0); index < remaining-granted; index++ {
243			name := active[index%int64(len(active))].Name
244			targets[name]++
245		}
246		return targets, nil
247	}
248	
249	func boundedActivity(value int64) int64 {
250		if value < 0 {
251			return 0
252		}
253		if value > 4 {
254			return 4
255		}
256		return value
257	}
258	
259	func percentOf(value int64, percent int32) int64 {
260		return value/100*int64(percent) + value%100*int64(percent)/100
261	}
262

