32		"sigs.k8s.io/controller-runtime/pkg/client"
33	)
34	
35	// poolPolicyManager is deliberately controller-local. A controller restart
36	// clears its counter baseline and therefore delays activity-derived decisions
37	// until another snapshot arrives, which is safer than reconstructing activity
38	// from stale annotations or status.
39	type poolPolicyManager struct {
40		mu       sync.Mutex
41		now      func() time.Time
42		lastRun  map[types.NamespacedName]time.Time
43		activity map[string]poolActivityRecord
44		config   map[types.NamespacedName]poolConfigRecord
45	}
46	
47	type poolActivityRecord struct {
48		successTotal int64
49		known        bool
50		lastActive   time.Time
51	}
52	
53	type poolConfigRecord struct {
54		raw        string
55		errorClass string
56	}
57	
58	func newPoolPolicyManager(now func() time.Time) *poolPolicyManager {
59		if now == nil {
60			now = time.Now
61		}
62		return &poolPolicyManager{
63			now:      now,
64			lastRun:  make(map[types.NamespacedName]time.Time),
65			activity: make(map[string]poolActivityRecord),
66			config:   make(map[types.NamespacedName]poolConfigRecord),
67		}
68	}
69	
70	// observeConfig records the latest annotation parse outcome and reports
71	// whether a warning or recovery Event is due. Deduplication keys on the
72	// annotation content because metadata edits do not bump the generation.
73	func (m *poolPolicyManager) observeConfig(
74		pool types.NamespacedName,
75		raw string,
76		errorClass string,
77	) (warn, recovered bool) {
78		m.mu.Lock()
79		defer m.mu.Unlock()
80		next := poolConfigRecord{raw: raw, errorClass: errorClass}
81		previous, known := m.config[pool]
82		m.config[pool] = next
83		if next.errorClass != "" {
84			return !known || previous != next, false
85		}
86		return false, known && previous.errorClass != ""
87	}
88	
89	// forgetConfig clears tracking once the annotation is removed, so a re-added
90	// policy is treated as fresh configuration.
91	func (m *poolPolicyManager) forgetConfig(pool types.NamespacedName) bool {
92		m.mu.Lock()
93		defer m.mu.Unlock()
94		_, known := m.config[pool]
95		delete(m.config, pool)
96		return known
97	}
98	
99	func (m *poolPolicyManager) begin(pool types.NamespacedName) bool {
100		m.mu.Lock()
101		defer m.mu.Unlock()
102		now := m.now()
103		if last, found := m.lastRun[pool]; found && now.Sub(last) < DefaultRequeueDuration {
104			return false
105		}
106		m.lastRun[pool] = now
107		return true
108	}
109	
110	func (m *poolPolicyManager) observe(
111		key string,
112		model RuntimeSnapshotModel,
113	) (poolRequestActivity, bool) {
114		if !model.RequestMetricsObserved || model.RequestSuccessTotal == nil {
115			return poolRequestActivity{}, false
116		}
117	
118		m.mu.Lock()
119		defer m.mu.Unlock()
120		now := m.now()
121		current := *model.RequestSuccessTotal
122		record := m.activity[key]
123		initialized := record.known && current >= record.successTotal
124		delta := int64(0)
125		if initialized {
126			delta = current - record.successTotal
127		}
128		inFlight := max(model.RequestsRunning, int64(0)) + max(model.RequestsWaiting, int64(0))
129		active := inFlight > 0 || delta > 0
130		if !initialized || active {
131			record.lastActive = now
132		}
133		record.successTotal = current
134		record.known = true
135		m.activity[key] = record
136		return poolRequestActivity{
137			Active:           active,
138			RequestsInFlight: inFlight,
139			CompletionDelta:  delta,
140			LastActive:       record.lastActive,
141			Initialized:      initialized,
142		}, true
143	}
144	
145	func (r *ModelClaimReconciler) poolPolicyManager() *poolPolicyManager {
146		if r.PoolPolicy != nil {
147			return r.PoolPolicy
148		}
149		// Production and normal tests initialize the manager. Keeping this fallback
150		// makes narrow reconciler unit tests safe without turning policy into a
151		// persistent or globally shared singleton.
152		return newPoolPolicyManager(time.Now)
153	}
154	
155	type poolPolicySource struct {
156		key        types.NamespacedName
157		deployment *appsv1.Deployment
158		policy     *poolPolicy
159	}
160	
161	// reconcilePoolPolicies finds the Deployment that owns each selected warm pod
162	// and runs an optional policy once per pool. ModelClaim reconciliation remains
163	// independent: any policy issue is logged and retried next tick rather than
164	// failing an otherwise healthy ModelClaim.
165	func (r *ModelClaimReconciler) reconcilePoolPolicies(ctx context.Context, candidates []corev1.Pod) {
166		seen := make(map[types.NamespacedName]struct{}, len(candidates))
167		manager := r.poolPolicyManager()
168		for i := range candidates {
169			deployment, err := r.poolDeploymentForPod(ctx, &candidates[i])
170			if err != nil {
171				klog.ErrorS(err, "unable to resolve ModelClaim pool deployment", "pod", klog.KObj(&candidates[i]))
172				continue
173			}
174			if deployment == nil {
175				continue
176			}
177			key := types.NamespacedName{Namespace: deployment.Namespace, Name: deployment.Name}
178			if _, done := seen[key]; done {
179				continue
180			}
181			seen[key] = struct{}{}
182			policy := r.resolvePoolPolicy(deployment, manager)
183			if policy == nil {
184				continue
185			}
186			if !manager.begin(key) {
187				continue
188			}
189			source := &poolPolicySource{key: key, deployment: deployment, policy: policy}
190			if err := r.reconcilePoolPolicy(ctx, source, manager); err != nil {
191				klog.ErrorS(err, "ModelClaim pool policy tick failed", "deployment", klog.KObj(deployment))
192			}
193		}
194	}
195	
196	func (r *ModelClaimReconciler) poolDeploymentForPod(
197		ctx context.Context,
198		pod *corev1.Pod,
199	) (*appsv1.Deployment, error) {
200		podOwner := metav1.GetControllerOf(pod)
201		if podOwner == nil || podOwner.Kind != "ReplicaSet" {
202			return nil, nil
203		}
204		replicaSet := &appsv1.ReplicaSet{}
205		if err := r.Get(ctx, types.NamespacedName{Namespace: pod.Namespace, Name: podOwner.Name}, replicaSet); err != nil {
206			return nil, err
207		}
208		replicaSetOwner := metav1.GetControllerOf(replicaSet)
209		if replicaSetOwner == nil || replicaSetOwner.Kind != "Deployment" {
210			return nil, nil
211		}
212		deployment := &appsv1.Deployment{}
213		key := types.NamespacedName{Namespace: pod.Namespace, Name: replicaSetOwner.Name}
214		if err := r.Get(ctx, key, deployment); err != nil {
215			return nil, err
216		}
217		return deployment, nil
218	}
219	
220	// resolvePoolPolicy parses the Deployment policy annotation and surfaces the
221	// outcome to operators through Deployment Events and the policy-valid gauge.
222	// Invalid configuration stays fail-closed: it returns nil so no KV plan runs.
223	func (r *ModelClaimReconciler) resolvePoolPolicy(
224		deployment *appsv1.Deployment,
225		manager *poolPolicyManager,
226	) *poolPolicy {
227		pool := types.NamespacedName{Namespace: deployment.Namespace, Name: deployment.Name}
228		raw := deployment.Annotations[constants.ModelPoolPolicyAnnotationKey]
229		if raw == "" {
230			if manager.forgetConfig(pool) {
231				clearPoolPolicyMetrics(pool)
232			}
233			return nil
234		}
235		policy, err := parsePoolPolicy(raw)
236		if err != nil {
237			errorClass := poolPolicyErrorClass(err)
238			setPoolPolicyValid(pool, false)
239			recordPolicyEvaluation(pool, policyResultSkipped, errorClass)
240			if warn, _ := manager.observeConfig(pool, raw, errorClass); warn {
241				r.Recorder.Eventf(deployment, corev1.EventTypeWarning, "InvalidPoolPolicy",
242					"invalid %s annotation (%s), pool policy disabled: %v",
243					constants.ModelPoolPolicyAnnotationKey, errorClass, err)
244				klog.ErrorS(err, "invalid ModelClaim pool policy annotation",
245					"deployment", klog.KObj(deployment), "errorClass", errorClass)
246			}
247			return nil
248		}
249		setPoolPolicyValid(pool, true)
250		if _, recovered := manager.observeConfig(pool, raw, ""); recovered {
251			r.Recorder.Eventf(deployment, corev1.EventTypeNormal, "PoolPolicyValid",
252				"%s annotation is valid again, pool policy execution resumed",
253				constants.ModelPoolPolicyAnnotationKey)
254		}
255		return policy
256	}
257	
258	func (r *ModelClaimReconciler) reconcilePoolPolicy(
259		ctx context.Context,
260		source *poolPolicySource,
261		manager *poolPolicyManager,
262	) error {
263		if source.policy.Reclaim == nil && source.policy.Lifecycle == nil {
264			recordPolicyEvaluation(source.key, policyResultSkipped, policyReasonNoReclaimPolicy)
265			return nil
266		}
267		pods, err := r.poolPolicyPods(ctx, source.deployment)
268		if err != nil {
269			recordPolicyEvaluation(source.key, policyResultFailed, policyReasonPodListError)
270			return err
271		}
272		if len(pods) == 0 {
273			recordPolicyEvaluation(source.key, policyResultSkipped, policyReasonNoPods)
274			return nil
275		}
276		for i := range pods {
277			pod := &pods[i]
278			snapshot, err := r.Runtime.Snapshot(ctx, pod.Status.PodIP, DefaultRuntimePort)
279			if err != nil {
280				recordPolicyEvaluation(source.key, policyResultFailed, policyReasonSnapshotError)
281				klog.V(4).InfoS("pool policy snapshot failed", "pod", klog.KObj(pod), "err", err)
282				continue
283			}
284			if snapshot == nil {
285				recordPolicyEvaluation(source.key, policyResultSkipped, policyReasonEmptySnapshot)
286				klog.V(4).InfoS("pool policy received empty runtime snapshot", "pod", klog.KObj(pod))
287				continue
288			}
289			if len(snapshot.Accelerators) != 1 {
290				// Dynamic KV limits remain held to the verified single-GPU contract
291				// until multi-GPU kvcached accounting is tested.
292				recordPolicyEvaluation(source.key, policyResultSkipped, policyReasonUnsupportedTopology)
293				klog.V(4).InfoS("pool policy skips non-single-GPU runtime", "pod", klog.KObj(pod))
294				continue
295			}
296			decisionTime := snapshot.ObservedAt
297			if decisionTime.IsZero() {
298				decisionTime = manager.now()
299			}
300			activities, observed := manager.observeSnapshot(pod, snapshot)
301			if source.policy.Reclaim != nil && !observed {
302				recordPolicyEvaluation(source.key, policyResultSkipped, policyReasonIncompleteMetrics)
303				klog.V(4).InfoS("pool KV policy waits for complete request observations", "pod", klog.KObj(pod))
304			} else if source.policy.Reclaim != nil {
305				models := modelsForKVPolicy(snapshot, activities)
306				targets, err := computePoolKVTargets(
307					source.policy.Reclaim.CapacityBytes,
308					source.policy.Reclaim.GuaranteedFloorPercent,
309					models,
310				)
311				if err != nil {
312					recordPolicyEvaluation(source.key, policyResultSkipped, policyReasonUnsafePlan)
313					klog.V(4).InfoS("pool policy did not produce a safe KV plan", "pod", klog.KObj(pod), "err", err)
314				} else {
315					applied, failed := 0, 0
316					for _, model := range snapshot.Models {
317						target, found := targets[model.ModelName]
318						if !found || target == model.KVCapacityBytes {
319							continue
320						}
321						operationID := fmt.Sprintf(
322							"pool-policy-kv/%s/%s/%s/%d/%d",
323							source.key.String(), pod.UID, snapshotActivityKey(model), target, decisionTime.UnixNano(),
324						)
325						response, err := r.Runtime.SetKVLimit(ctx, pod.Status.PodIP, DefaultRuntimePort, &SetKVLimitRequest{
326							ModelName: model.ModelName, LimitBytes: target, OperationID: operationID,
327						})
328						switch {
329						case err != nil:
330							failed++
331							recordPolicyAction(source.key, policyActionSetKVLimit, policyResultFailed, policyReasonRuntimeError)
332							klog.ErrorS(err, "pool policy could not apply KV limit", "pod", klog.KObj(pod), "model", model.ModelName, "target", target)
333						case response == nil || !response.Applied:
334							recordPolicyAction(source.key, policyActionSetKVLimit, policyResultSkipped, policyReasonNoChange)
335						default:
336							applied++
337							recordPolicyAction(source.key, policyActionSetKVLimit, policyResultApplied, policyReasonApplied)
338						}
339					}
340					switch {
341					case failed > 0:
342						recordPolicyEvaluation(source.key, policyResultFailed, policyReasonRuntimeError)
343					case applied > 0:
344						recordPolicyEvaluation(source.key, policyResultApplied, policyReasonApplied)
345					default:
346						recordPolicyEvaluation(source.key, policyResultSkipped, policyReasonNoChange)
347					}
348				}
349			}
350			if source.policy.Lifecycle != nil && !observed {
351				klog.V(4).InfoS("pool lifecycle policy waits for complete request observations", "pod", klog.KObj(pod))
352			} else if source.policy.Lifecycle != nil {
353				r.reconcilePoolIdleSleep(ctx, source, manager, pod, snapshot, activities)
354			}
355		}
356		return nil
357	}
358	
359	func (m *poolPolicyManager) observeSnapshot(
360		pod *corev1.Pod,
361		snapshot *RuntimeSnapshot,
362	) (map[string]poolRequestActivity, bool) {
363		activities := make(map[string]poolRequestActivity, len(snapshot.Models))
364		for i := range snapshot.Models {
365			model := snapshot.Models[i]
366			if model.Phase != runtimePhaseActive || !model.Alive || !model.Ready {
367				continue
368			}
369			activityKey := snapshotActivityKey(model)
370			activity, observed := m.observe(string(pod.UID)+"/"+activityKey, model)
371			if !observed {
372				return nil, false
373			}
374			activities[activityKey] = activity
375		}
376		return activities, true
377	}
378	
379	func modelsForKVPolicy(
380		snapshot *RuntimeSnapshot,
381		activities map[string]poolRequestActivity,
382	) []poolKVModel {
383		models := make([]poolKVModel, 0, len(snapshot.Models))
384		for i := range snapshot.Models {
385			model := snapshot.Models[i]
386			if model.Phase != runtimePhaseActive || !model.Alive || !model.Ready {
387				continue
388			}
389			if model.KVCapacityBytes <= 0 {
390				return nil
391			}
392			models = append(models, poolKVModel{
393				Name:            model.ModelName,
394				KVUsedBytes:     model.KVUsedBytes,
395				KVCapacityBytes: model.KVCapacityBytes,
396				Activity:        activities[snapshotActivityKey(model)],
397			})
398		}
399		return models
400	}
401	
402	func (r *ModelClaimReconciler) reconcilePoolIdleSleep(
403		ctx context.Context,
404		source *poolPolicySource,
405		manager *poolPolicyManager,
406		pod *corev1.Pod,
407		snapshot *RuntimeSnapshot,
408		activities map[string]poolRequestActivity,
409	) {
410		claims := &modelv1alpha1.ModelClaimList{}
411		if err := r.List(ctx, claims, client.InNamespace(pod.Namespace)); err != nil {
412			klog.ErrorS(err, "pool lifecycle policy could not list ModelClaims", "pod", klog.KObj(pod))
413			return
414		}
415		idleAfter := time.Duration(source.policy.Lifecycle.SleepAfterSeconds) * time.Second
416		for i := range snapshot.Models {
417			model := snapshot.Models[i]
418			if model.Phase != runtimePhaseActive || !model.Alive || !model.Ready {
419				continue
420			}
421			activity, found := activities[snapshotActivityKey(model)]
422			if !found || !activity.Initialized || activity.Active {
423				continue
424			}
425			idleSince := activity.LastActive
426			if model.LastTransition != nil && model.LastTransition.After(idleSince) {
427				idleSince = *model.LastTransition
428			}
429			if idleSince.IsZero() || manager.now().Sub(idleSince) < idleAfter {
430				continue
431			}
432	
433			claim := claimForRuntimeSnapshot(claims, model)
434			if claim == nil || !isVLLMModel(claim) {
435				continue
436			}
437			port, active := activeClaimInstancePort(claim, pod.Name)
438			if !active {
439				continue
440			}
441			if err := r.annotateWarmPodWithState(
442				ctx, claim, pod, 0, constants.ModelClaimRoutingStateSleeping,
443			); err != nil {
444				klog.ErrorS(err, "pool lifecycle policy could not de-route idle engine", "pod", klog.KObj(pod), "model", model.ModelName)
445				continue
446			}
447			operationID := fmt.Sprintf(
448				"pool-policy-sleep/%s/%s/%s/%d",
449				source.key.String(), pod.UID, snapshotActivityKey(model), idleSince.UnixNano(),
450			)
451			if _, err := r.Runtime.Sleep(ctx, pod.Status.PodIP, DefaultRuntimePort, &SleepRequest{
452				ModelName: model.ModelName, Level: 1, OperationID: operationID,
453			}); err != nil {
454				if restoreErr := r.annotateWarmPodWithState(
455					ctx, claim, pod, port, constants.ModelClaimRoutingStateActive,
456				); restoreErr != nil {
457					klog.ErrorS(restoreErr, "pool lifecycle policy could not restore route", "pod", klog.KObj(pod), "model", model.ModelName)
458				}
459				klog.ErrorS(err, "pool lifecycle policy could not sleep idle engine", "pod", klog.KObj(pod), "model", model.ModelName)
460				continue
461			}
462			if err := r.markClaimInstanceSleeping(ctx, claim, pod.Name); err != nil {
463				klog.ErrorS(err, "pool lifecycle policy could not persist sleeping state", "claim", klog.KObj(claim), "pod", klog.KObj(pod))
464				continue
465			}
466			r.Recorder.Eventf(
467				claim, corev1.EventTypeNormal, "Sleeping",
468				"model %s idle past %ds; sleeping engine on pod %s",
469				model.ModelName, source.policy.Lifecycle.SleepAfterSeconds, pod.Name,
470			)
471		}
472	}
473	
474	func snapshotActivityKey(model RuntimeSnapshotModel) string {
475		if model.IPCName != "" {
476			return model.IPCName
477		}
478		return model.ModelName
479	}
480	
481	func claimForRuntimeSnapshot(
482		claims *modelv1alpha1.ModelClaimList,
483		model RuntimeSnapshotModel,
484	) *modelv1alpha1.ModelClaim {
485		if model.ClaimRef == nil || model.ClaimRef.UID == "" {
486			return nil
487		}
488		for i := range claims.Items {
489			claim := &claims.Items[i]
490			if claim.Namespace == model.ClaimRef.Namespace &&
491				claim.Name == model.ClaimRef.Name && string(claim.UID) == model.ClaimRef.UID {
492				return claim
493			}
494		}
495		return nil
496	}
497	
498	func activeClaimInstancePort(pm *modelv1alpha1.ModelClaim, podName string) (int32, bool) {
499		for _, instance := range pm.Status.Instances {
500			if instance.Pod == podName && instance.Phase == modelv1alpha1.ModelClaimActive {
501				return instance.Port, true
502			}
503		}
504		return 0, false
505	}
506	
507	func (r *ModelClaimReconciler) markClaimInstanceSleeping(
508		ctx context.Context,
509		pm *modelv1alpha1.ModelClaim,
510		podName string,
511	) error {
512		latest := &modelv1alpha1.ModelClaim{}
513		if err := r.Get(ctx, types.NamespacedName{Namespace: pm.Namespace, Name: pm.Name}, latest); err != nil {
514			return err
515		}
516		changed := false
517		for i := range latest.Status.Instances {
518			if latest.Status.Instances[i].Pod != podName {
519				continue
520			}
521			if latest.Status.Instances[i].Phase != modelv1alpha1.ModelClaimSleeping {
522				latest.Status.Instances[i].Phase = modelv1alpha1.ModelClaimSleeping
523				changed = true
524			}
525			break
526		}
527		if !changed {
528			return nil
529		}
530		r.recomputeReadiness(latest)
531		setClaimGauges(latest)
532		return r.Status().Update(ctx, latest)
533	}
534	
535	func (r *ModelClaimReconciler) poolPolicyPods(
536		ctx context.Context,
537		deployment *appsv1.Deployment,
538	) ([]corev1.Pod, error) {
539		if deployment.Spec.Selector == nil {
540			return nil, fmt.Errorf("deployment %s has no selector", deployment.Name)
541		}
542		selector, err := metav1.LabelSelectorAsSelector(deployment.Spec.Selector)
543		if err != nil {
544			return nil, err
545		}
546		podList := &corev1.PodList{}
547		if err := r.List(ctx, podList,
548			client.InNamespace(deployment.Namespace),
549			client.MatchingLabelsSelector{Selector: selector},
550		); err != nil {
551			return nil, err
552		}
553		pods := make([]corev1.Pod, 0, len(podList.Items))
554		for i := range podList.Items {
555			pod := podList.Items[i]
556			if pod.Labels[constants.ModelPoolLabelEnabled] != constants.ModelPoolLabelEnabledValue ||
557				pod.Status.Phase != corev1.PodRunning || pod.Status.PodIP == "" || !pod.DeletionTimestamp.IsZero() {
558				continue
559			}
560			pods = append(pods, pod)
561		}
562		return pods, nil
563	}
